-- Converted: CREATE TABLE sales.recovered_after_error -> CREATE TABLE SALES.RECOVERED_AFTER_ERROR; INTEGER kept as INTEGER (NUMBER(38,0))
-- Reason: Plain Teradata table (MULTISET by default in ANSI mode, SET in Teradata mode) with no index clause; only the name needs the naming-map form
CREATE TABLE SALES.RECOVERED_AFTER_ERROR (
  id INTEGER
);

-- Converted: CREATE ROLE reader -> CREATE ROLE IF NOT EXISTS READER (unquoted, resolves uppercase)
-- Reason: Roles are account-level in Snowflake and may already exist; IF NOT EXISTS keeps the deployment re-runnable without dropping existing grants
CREATE ROLE IF NOT EXISTS READER;

-- Converted: CREATE ROLE operator -> CREATE ROLE IF NOT EXISTS OPERATOR (unquoted, resolves uppercase)
-- Reason: Roles are account-level in Snowflake and may already exist; IF NOT EXISTS keeps the deployment re-runnable without dropping existing grants
CREATE ROLE IF NOT EXISTS OPERATOR;

-- Converted: CREATE ROLE auditor -> CREATE ROLE IF NOT EXISTS AUDITOR (unquoted, resolves uppercase)
-- Reason: Roles are account-level in Snowflake and may already exist; IF NOT EXISTS keeps the deployment re-runnable without dropping existing grants
CREATE ROLE IF NOT EXISTS AUDITOR;

-- Converted: GRANT reader TO analyst -> GRANT ROLE READER TO USER ANALYST
-- Reason: Snowflake requires the explicit ROLE and USER keywords when granting a role to a user
GRANT ROLE READER TO USER ANALYST;

-- Converted: GRANT operator TO loader -> GRANT ROLE OPERATOR TO USER LOADER
-- Reason: Snowflake requires the explicit ROLE and USER keywords when granting a role to a user
GRANT ROLE OPERATOR TO USER LOADER;

-- Converted: SET TABLE -> standard permanent table; dropped PRIMARY INDEX (branch_id); INTEGER/BIGINT kept as Snowflake INTEGER/BIGINT (aliases of NUMBER(38,0), a superset of Teradata int32/int64 range); DECIMAL(p,s) kept as NUMBER(p,s)
